		fmt.Printf("Внешний REST эндпоинт: %-20s -> Внутренний gRPC сервис: %s\n", path, target)
	}
}

func main() {
	gw := NewAPIGateway()
	gw.RouteInfo()
	fmt.Println("Шлюз объединяет OpenAPI v3 документацию и транслирует JSON в двоичный gRPC.")
